"""Write web/js/unitdata.js from the Python unit tables, so the web app can't drift from them."""
import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(root))
from recipelib import category_data, units  # noqa: E402
from recipelib.editing import UNIT_CHOICES  # noqa: E402

canon = sorted({v for v in units.MM_UNITS.values()})
out = (
    "// Generated by tools/gen_unitdata.py. Do not edit by hand.\n"
    f"export const ALIASES = {json.dumps(units._ALIASES, indent=1)};\n"
    f"export const CANON = {json.dumps(canon)};\n"
    f"export const PLURALS = {json.dumps(units._PLURALS, indent=1)};\n"
    f"export const UNIT_CHOICES = {json.dumps(UNIT_CHOICES)};\n"
)
(root / "web" / "js").mkdir(parents=True, exist_ok=True)
groups = (
    "// Generated by tools/gen_unitdata.py from recipelib/category_data.py. Do not edit by hand.\n"
    f"export const SECTIONS = {json.dumps(category_data.SECTIONS, indent=1)};\n"
)
(root / "web" / "js" / "groups.js").write_text(groups)
(root / "web" / "js" / "unitdata.js").write_text(out)
print("wrote web/js/unitdata.js and web/js/groups.js")
